class Customer {
  + Address : string
  + VATNumber : string
  + HeadOfficeAddress : string
}

class Product {
  + Name : string
  + StockLevel : int
}

class Order {
  + OrderDate : date
  + PaymentDate : date
  + IsFullyShipped : boolean
}

class OrderLine {
  + Quantity : int
  + IsShipped : boolean
}

class Invoice {
  + InvoiceDate : date
}

class Delivery {
  + Status : string
  + PackingDate : date
  + ShippingDate : date
  + ReceivedDate : date
}

class DeliveryLine {
}

class Warehouse {
  + Address : string
}

Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives
Order "1" *-- "1..*" OrderLine : contains
Order "1" -- "0..1" Invoice : billedBy
OrderLine "1" -- "*" DeliveryLine : partOf
Delivery "1" *-- "1..*" DeliveryLine : contains
Delivery "*" -- "1" Warehouse : deliveredTo
OrderLine "*" -- "1" Product : refersTo

@enduml

